using System;
using Framework.AI.Core;
using Framework.AI.Memory;
using Framework.AI.Perception;
using Framework.Grid;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Parameters;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.AI.Core
{
    /// <summary>
    /// 迷路内の敵エージェントが利用する
    /// 実行時情報と依存関係を管理する。
    /// </summary>
    /// <remarks>
    /// 行動判断や移動処理は担当しない。
    /// ステージと移動制御の初期化後に生成する。
    /// 使用終了時にはDisposeを呼び出す。
    /// </remarks>
    public sealed class MazeEnemyContext : IDisposable
    {
        /// <summary>
        /// コンテキストが解放されているか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 記憶機能が使用可能な最小時間。単位は秒。
        /// </summary>
        private const double MinimumMemoryDuration = 0.001d;

        /// <summary>
        /// 汎用エージェントコンテキスト。
        /// </summary>
        public AgentContext<MazeEnemyParameter> Agent { get; }

        /// <summary>
        /// エージェントの個体識別子。
        /// </summary>
        public Guid Id => Agent.Id;

        /// <summary>
        /// エージェントの表示名。
        /// </summary>
        public string Name => Agent.Name;

        /// <summary>
        /// 個体固有の実行時パラメーターセット。
        /// </summary>
        public ParameterSet<MazeEnemyParameter> Parameters =>
            Agent.Parameters;

        /// <summary>
        /// ステージの管理コンポーネント。
        /// </summary>
        public MazeStageManager StageManager { get; }

        /// <summary>
        /// コンテキスト生成時の迷路データ。
        /// </summary>
        public GridMap<MazeCell> Map { get; }

        /// <summary>
        /// エージェントの移動制御コンポーネント。
        /// </summary>
        public GridMovementController Movement { get; }

        /// <summary>
        /// エージェントの初期出現位置。
        /// グリッド座標で保持する。
        /// </summary>
        public Vector2Int SpawnPosition { get; }

        /// <summary>
        /// 縄張りの中心位置。
        /// グリッド座標で保持する。
        /// </summary>
        public Vector2Int TerritoryCenter { get; private set; }

        /// <summary>
        /// プレイヤーなどを認識する視覚センサー。
        /// </summary>
        public GridVisionSensor<MazeCell> VisionSensor { get; }

        /// <summary>
        /// 脅威を認識する視覚センサー。
        /// </summary>
        public GridVisionSensor<MazeCell> ThreatVisionSensor { get; }

        /// <summary>
        /// 認識対象の記憶を管理する。
        /// </summary>
        public PerceptionMemory<Vector2Int> PerceptionMemory { get; }

        /// <summary>
        /// セルの訪問履歴を管理する。
        /// </summary>
        public SpatialMemory<Vector2Int> SpatialMemory { get; }

        /// <summary>
        /// 最後に到達したセルのグリッド座標。
        /// </summary>
        public Vector2Int CurrentCell => Movement.CurrentCell;

        /// <summary>
        /// 現在の移動方向。
        /// </summary>
        public Vector2Int CurrentDirection =>
            Movement.CurrentDirection;

        /// <summary>
        /// 現在の移動先セル。
        /// </summary>
        public Vector2Int TargetCell => Movement.TargetCell;

        /// <summary>
        /// セル間を移動中であるか。
        /// </summary>
        public bool IsTraversing => Movement.IsTraversing;

        /// <summary>
        /// セルの中心に位置しているか。
        /// </summary>
        public bool IsAtCellCenter => Movement.IsAtCellCenter;

        /// <summary>
        /// ステージ内の経過時間。単位は秒。
        /// </summary>
        /// <remarks>
        /// ステージ管理側のスケール時間を参照する。
        /// </remarks>
        public double CurrentTime => StageManager.ElapsedTime;

        /// <summary>
        /// コンテキストが解放済みであるか。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 現在のステージで使用可能な状態であるか。
        /// </summary>
        public bool IsValid =>
            !isDisposed &&
            StageManager != null &&
            Movement != null &&
            Movement.IsInitialized &&
            !Parameters.IsDisposed &&
            StageManager.HasStage &&
            ReferenceEquals(StageManager.Map, Map);

        /// <summary>
        /// エージェントが行動可能な状態であるか。
        /// </summary>
        /// <remarks>
        /// Agent自身の状態判定は呼び出し側で行う。
        /// </remarks>
        public bool CanAct =>
            IsValid &&
            StageManager.IsPlaying &&
            !Movement.IsPaused;

        /// <summary>
        /// 認識対象の記憶機能が有効であるか。
        /// </summary>
        public bool IsPerceptionMemoryEnabled =>
            IsValid &&
            Parameters.GetValue(
                MazeEnemyParameter.MemoryDuration) > 0f;

        /// <summary>
        /// 敵エージェントの実行コンテキストを生成する。
        /// </summary>
        /// <param name="agent">
        /// 初期化済みの汎用エージェント情報
        /// </param>
        /// <param name="stageManager">
        /// ステージ管理コンポーネント
        /// </param>
        /// <param name="movement">
        /// 初期化済みの移動制御コンポーネント
        /// </param>
        /// <param name="spawnPosition">
        /// 初期出現位置。グリッド座標
        /// </param>
        /// <exception cref="ArgumentNullException">
        /// 必須の依存関係が指定されていない場合。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// ステージや移動制御が未初期化の場合、
        /// または必要なパラメーターが不足している場合。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// 初期出現位置が通行可能でない場合。
        /// </exception>
        public MazeEnemyContext(
            AgentContext<MazeEnemyParameter> agent,
            MazeStageManager stageManager,
            GridMovementController movement,
            Vector2Int spawnPosition)
        {
            if (agent == null)
            {
                throw new ArgumentNullException(nameof(agent));
            }

            if (stageManager == null)
            {
                throw new ArgumentNullException(
                    nameof(stageManager));
            }

            if (movement == null)
            {
                throw new ArgumentNullException(
                    nameof(movement));
            }

            if (agent.Parameters.IsDisposed)
            {
                throw new ObjectDisposedException(
                    nameof(agent.Parameters));
            }

            if (!stageManager.HasStage ||
                stageManager.Map == null)
            {
                throw new InvalidOperationException(
                    "ステージが生成されていません。");
            }

            if (!movement.IsInitialized)
            {
                throw new InvalidOperationException(
                    "移動制御が初期化されていません。");
            }

            ValidateParameters(agent.Parameters);

            if (!stageManager.IsWalkable(spawnPosition))
            {
                throw new ArgumentException(
                    "初期出現位置が通行可能ではありません。",
                    nameof(spawnPosition));
            }

            if (!stageManager.IsWalkable(movement.CurrentCell))
            {
                throw new InvalidOperationException(
                    "移動制御の現在位置が通行可能ではありません。");
            }

            Agent = agent;
            StageManager = stageManager;
            Movement = movement;
            Map = stageManager.Map;

            SpawnPosition = spawnPosition;
            TerritoryCenter = spawnPosition;

            // 個体ごとの視覚センサーを生成する。
            VisionSensor = new GridVisionSensor<MazeCell>(
                Map,
                BlocksSight,
                Parameters.GetValue(
                    MazeEnemyParameter.DetectionRange),
                360f);

            // 脅威認識には独立した認識距離を使用する。
            ThreatVisionSensor =
                new GridVisionSensor<MazeCell>(
                    Map,
                    BlocksSight,
                    Parameters.GetValue(
                        MazeEnemyParameter.ThreatDetectionRange),
                    360f);

            // 個体固有の記憶領域を生成する。
            PerceptionMemory =
                new PerceptionMemory<Vector2Int>(
                    GetEffectiveMemoryDuration());

            SpatialMemory =
                new SpatialMemory<Vector2Int>();

            // 初期位置を訪問済みとして登録する。
            SpatialMemory.RecordVisit(
                Movement.CurrentCell,
                CurrentTime);

            // パラメーター変更を認識機能へ反映する。
            Parameters.ValueChanged +=
                HandleParameterValueChanged;
        }

        /// <summary>
        /// 指定されたパラメーターの現在値を取得する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <returns>補正適用後の実行時の値</returns>
        public float GetParameterValue(
            MazeEnemyParameter id)
        {
            EnsureValid();

            return Parameters.GetValue(id);
        }

        /// <summary>
        /// 指定されたパラメーターの正規化値を取得する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <returns>0から1までの正規化値</returns>
        public float GetNormalizedParameterValue(
            MazeEnemyParameter id)
        {
            EnsureValid();

            return Parameters.GetNormalizedValue(id);
        }

        /// <summary>
        /// 指定されたセルが通行可能であるか確認する。
        /// </summary>
        /// <param name="position">
        /// 確認対象のグリッド座標
        /// </param>
        /// <returns>
        /// 有効なステージ内で通行可能な場合はtrue
        /// </returns>
        public bool IsWalkable(Vector2Int position)
        {
            return IsValid &&
                StageManager.IsWalkable(position);
        }

        /// <summary>
        /// 縄張りの中心位置を変更する。
        /// </summary>
        /// <param name="position">
        /// 新しい中心位置。グリッド座標
        /// </param>
        /// <returns>
        /// 有効な通行可能セルを設定できた場合はtrue
        /// </returns>
        public bool TrySetTerritoryCenter(
            Vector2Int position)
        {
            if (!IsWalkable(position))
            {
                return false;
            }

            TerritoryCenter = position;

            return true;
        }

        /// <summary>
        /// 縄張りの中心を初期出現位置へ戻す。
        /// </summary>
        /// <returns>
        /// 初期出現位置へ戻せた場合はtrue
        /// </returns>
        public bool ResetTerritoryCenter()
        {
            return TrySetTerritoryCenter(SpawnPosition);
        }

        /// <summary>
        /// 指定されたセルの訪問を記録する。
        /// </summary>
        /// <param name="position">
        /// 訪問したセルのグリッド座標
        /// </param>
        /// <returns>
        /// 新しい訪問記録を登録できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 呼び出し側が実際のセル到達時に実行する。
        /// 同一セルの同一時刻の記録は重複登録しない。
        /// </remarks>
        public bool RecordVisit(Vector2Int position)
        {
            if (!IsWalkable(position))
            {
                return false;
            }

            return SpatialMemory.RecordVisit(
                position,
                CurrentTime);
        }

        /// <summary>
        /// 現在位置の訪問を記録する。
        /// </summary>
        /// <returns>
        /// セル中心で新しい訪問を記録できた場合はtrue
        /// </returns>
        public bool RecordCurrentVisit()
        {
            if (!IsValid || !IsAtCellCenter)
            {
                return false;
            }

            return RecordVisit(CurrentCell);
        }

        /// <summary>
        /// 認識した対象の情報を記憶する。
        /// </summary>
        /// <param name="stimulus">認識対象の情報</param>
        /// <returns>
        /// 新しい認識情報を記憶できた場合はtrue
        /// </returns>
        public bool RememberObservation(
            PerceptionStimulus<Vector2Int> stimulus)
        {
            if (!IsPerceptionMemoryEnabled ||
                !stimulus.IsValid ||
                stimulus.Timestamp > CurrentTime ||
                !Map.IsInside(stimulus.Position))
            {
                return false;
            }

            return PerceptionMemory.Remember(stimulus);
        }

        /// <summary>
        /// 指定された対象の記憶を取得する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="stimulus">
        /// 最後に認識した情報。失敗時は既定値
        /// </param>
        /// <param name="confidence">
        /// 時間経過を反映した信頼度。失敗時は0
        /// </param>
        /// <returns>
        /// 有効な記憶を取得できた場合はtrue
        /// </returns>
        public bool TryRecallObservation(
            Guid sourceId,
            out PerceptionStimulus<Vector2Int> stimulus,
            out float confidence)
        {
            stimulus = default;
            confidence = 0f;

            if (!IsPerceptionMemoryEnabled)
            {
                return false;
            }

            return PerceptionMemory.TryRecall(
                sourceId,
                CurrentTime,
                out stimulus,
                out confidence);
        }

        /// <summary>
        /// 保持期限を過ぎた認識情報を削除する。
        /// </summary>
        /// <returns>削除した記憶の件数</returns>
        public int RemoveExpiredObservations()
        {
            if (!IsValid)
            {
                return 0;
            }

            if (!IsPerceptionMemoryEnabled)
            {
                int count = PerceptionMemory.Count;

                PerceptionMemory.Clear();

                return count;
            }

            return PerceptionMemory.RemoveExpired(
                CurrentTime);
        }

        /// <summary>
        /// 指定されたセルの未訪問評価を取得する。
        /// </summary>
        /// <param name="position">
        /// 評価対象のグリッド座標
        /// </param>
        /// <returns>
        /// 0から1までの未訪問評価。
        /// 通行不可能な場合は0
        /// </returns>
        public float GetUnvisitedScore(
            Vector2Int position)
        {
            if (!IsWalkable(position))
            {
                return 0f;
            }

            float duration = Parameters.GetValue(
                MazeEnemyParameter.VisitMemoryDuration);

            // 保持時間が0の場合は訪問履歴を評価に使用しない。
            if (duration <= 0f)
            {
                return 1f;
            }

            return SpatialMemory.GetUnvisitedScore(
                position,
                CurrentTime,
                duration);
        }

        /// <summary>
        /// 認識対象の記憶とセルの訪問履歴を初期化する。
        /// </summary>
        /// <remarks>
        /// パラメーターや縄張りの中心は変更しない。
        /// 現在位置が通行可能な場合は再登録する。
        /// </remarks>
        public void ClearMemories()
        {
            EnsureValid();

            PerceptionMemory.Clear();
            SpatialMemory.Clear();

            if (IsWalkable(CurrentCell))
            {
                SpatialMemory.RecordVisit(
                    CurrentCell,
                    CurrentTime);
            }
        }

        /// <summary>
        /// コンテキストが所有するリソースを解放する。
        /// </summary>
        /// <remarks>
        /// 外部から受け取ったParameterSet、
        /// StageManager、Movementは破棄しない。
        /// 複数回呼び出しても安全。
        /// </remarks>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            isDisposed = true;

            Parameters.ValueChanged -=
                HandleParameterValueChanged;

            PerceptionMemory.Clear();
            SpatialMemory.Clear();
        }

        /// <summary>
        /// 必要なパラメーターが登録されているか検証する。
        /// </summary>
        /// <param name="parameters">
        /// 検証対象のパラメーターセット
        /// </param>
        /// <exception cref="InvalidOperationException">
        /// 必要なパラメーターが存在しない場合。
        /// </exception>
        private static void ValidateParameters(
            ParameterSet<MazeEnemyParameter> parameters)
        {
            foreach (var definition in
                MazeEnemyParameterCatalog.Definitions)
            {
                if (!parameters.Contains(definition.Id))
                {
                    throw new InvalidOperationException(
                        $"敵パラメーターが不足しています：" +
                        $"{definition.Id}");
                }
            }
        }

        /// <summary>
        /// 指定されたセルが視界を遮るか確認する。
        /// </summary>
        /// <param name="position">
        /// 確認対象のグリッド座標
        /// </param>
        /// <returns>
        /// 壁または範囲外の場合はtrue
        /// </returns>
        private bool BlocksSight(Vector2Int position)
        {
            if (!Map.TryGetCell(position, out var cell))
            {
                return true;
            }

            return !cell.IsWalkable;
        }

        /// <summary>
        /// 記憶機能へ設定可能な保持時間を取得する。
        /// </summary>
        /// <returns>正の記憶保持時間。単位は秒</returns>
        private double GetEffectiveMemoryDuration()
        {
            float duration = Parameters.GetValue(
                MazeEnemyParameter.MemoryDuration);

            return Math.Max(
                MinimumMemoryDuration,
                duration);
        }

        /// <summary>
        /// パラメーター変更を関連機能へ反映する。
        /// </summary>
        /// <param name="id">変更された識別子</param>
        /// <param name="previousValue">変更前の値</param>
        /// <param name="newValue">変更後の値</param>
        private void HandleParameterValueChanged(
            MazeEnemyParameter id,
            float previousValue,
            float newValue)
        {
            if (!IsValid)
            {
                return;
            }

            switch (id)
            {
                case MazeEnemyParameter.DetectionRange:

                    VisionSensor.Configure(
                        newValue,
                        VisionSensor.FieldOfView);

                    break;

                case MazeEnemyParameter.ThreatDetectionRange:

                    ThreatVisionSensor.Configure(
                        newValue,
                        ThreatVisionSensor.FieldOfView);

                    break;

                case MazeEnemyParameter.MemoryDuration:

                    // 保持時間0は記憶機能の無効化として扱う。
                    if (newValue <= 0f)
                    {
                        PerceptionMemory.Clear();
                    }

                    PerceptionMemory.SetRetentionDuration(
                        GetEffectiveMemoryDuration());

                    PerceptionMemory.RemoveExpired(
                        CurrentTime);

                    break;
            }
        }

        /// <summary>
        /// コンテキストが使用可能な状態か検証する。
        /// </summary>
        /// <exception cref="ObjectDisposedException">
        /// コンテキストが解放済みの場合。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 現在のステージで使用できない場合。
        /// </exception>
        private void EnsureValid()
        {
            if (isDisposed)
            {
                throw new ObjectDisposedException(
                    nameof(MazeEnemyContext));
            }

            if (!IsValid)
            {
                throw new InvalidOperationException(
                    "敵コンテキストが無効な状態です。");
            }
        }
    }
}
